// PL_Validate_OR_Handoff — v1.0
const input = $json;
let candidate = input;
if (typeof input.chatInput === 'string' && !input.payload && !input.status_kind) {
  try { candidate = JSON.parse(input.chatInput); } catch (e) { candidate = input; }
}
function invalid(code, message, missing) {
  return [{ json: { _valid: 'false', error_code: code, error_message: message, missing_fields: (missing && missing.length ? missing : ['root']) } }];
}
if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
  return invalid('INVALID_HANDOFF_INPUT', 'Input is not a JSON object.', ['root']);
}
const requiredTop = ['status_kind', 'result_type', 'payload'];
const missing = [];
for (const key of requiredTop) { if (!(key in candidate)) missing.push(key); }
if (missing.length) return invalid('INVALID_HANDOFF_INPUT', 'Required handoff fields are missing.', missing);
const payload = candidate.payload;
if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return invalid('INVALID_HANDOFF_INPUT', 'payload must be an object.', ['payload']);
const requiredPayload = ['tenant_id','thread_id','execution_id','trigger_message_id','idempotency_key','execution_status','planning_allowed','allowed_next_stage','orchestrator_input'];
for (const key of requiredPayload) { if (!(key in payload)) missing.push(`payload.${key}`); }
if (missing.length) return invalid('INVALID_HANDOFF_INPUT', 'Required handoff payload fields are missing.', [...new Set(missing)].sort());
if (candidate.status_kind !== 'success') return invalid('INVALID_HANDOFF_INPUT', 'status_kind must be success.', ['status_kind']);
if (candidate.result_type !== 'handoff') return invalid('INVALID_HANDOFF_INPUT', 'result_type must be handoff.', ['result_type']);
if (String(payload.execution_status) !== 'initialized') return invalid('CONTEXT_MISMATCH', 'Execution context is not initialized.', ['payload.execution_status']);
if (payload.planning_allowed !== true) return invalid('INVALID_HANDOFF_INPUT', 'planning_allowed must be true.', ['payload.planning_allowed']);
if (String(payload.allowed_next_stage) !== 'WF-PL-01') return invalid('INVALID_HANDOFF_INPUT', 'allowed_next_stage must be WF-PL-01.', ['payload.allowed_next_stage']);
return [{
  json: {
    _valid: 'true',
    _normalized_or_handoff: {
      status_kind: 'success',
      result_type: 'handoff',
      module_name: candidate.module_name || 'orchestrator_input_handoff',
      payload: {
        tenant_id: String(payload.tenant_id),
        thread_id: String(payload.thread_id),
        execution_id: String(payload.execution_id),
        trigger_message_id: String(payload.trigger_message_id),
        idempotency_key: String(payload.idempotency_key),
        execution_status: String(payload.execution_status),
        planning_allowed: true,
        allowed_next_stage: 'WF-PL-01',
        orchestrator_input: payload.orchestrator_input || {},
        planner_context: payload.planner_context || candidate.planner_context || {},
        warnings: Array.isArray(payload.warnings) ? payload.warnings.slice() : []
      }
    }
  }
}];

const h = $json._normalized_or_handoff.payload;
return [{ json: {
  tenant_id: h.tenant_id,
  thread_id: h.thread_id,
  execution_id: h.execution_id,
  trigger_message_id: h.trigger_message_id,
  idempotency_key: h.idempotency_key,
  execution_status: h.execution_status,
  planner_context: h.planner_context || {},
  warnings: Array.isArray(h.warnings) ? h.warnings : []
}}];

const row = $json;
if (!row.execution_id || !row.tenant_id || !row.thread_id || !row.trigger_message_id) {
  return [{ json: {
    _verified: 'false',
    error_code: 'CONTEXT_MISMATCH',
    error_message: 'Execution context row was not found or is incomplete.',
    missing_fields: ['execution_context']
  }}];
}
return [{ json: {
  _verified: 'true',
  execution_id: String(row.execution_id),
  tenant_id: String(row.tenant_id),
  thread_id: String(row.thread_id),
  trigger_message_id: String(row.trigger_message_id),
  idempotency_key: String(row.idempotency_key || ''),
  execution_status: String(row.status || ''),
  ttl_seconds: row.ttl_seconds,
  warnings: []
}}];

return [{ json: {
  module_registry: [
    { module_name: 'task_module', module_type: 'executor', capabilities: ['create_task','list_tasks','update_task','complete_task','delete_task'] },
    { module_name: 'reminder_module', module_type: 'executor', capabilities: ['create_reminder','list_reminders','update_reminder','cancel_reminder'] },
    { module_name: 'memory_module', module_type: 'executor', capabilities: ['store_memory','search_memory'] },
    { module_name: 'improvement_module', module_type: 'executor', capabilities: ['capture_feedback'] },
    { module_name: 'watcher_module_basic', module_type: 'observer', capabilities: ['produce_observation'] }
  ]
}}];

// PL_Build_Planner_Input — v1.1 (live fix: resolve upstream nodes by name,
// fail-closed on verify_context_match failure before considering registry state)
function safeNode(name) {
  try { const it = $(name).first(); return (it && it.json) ? it.json : {}; } catch (e) { return {}; }
}
const verify   = safeNode('PL_Verify_Context_Match');
const extract  = safeNode('PL_Extract_Planning_Input');
const registry = $json && Array.isArray($json.module_registry) ? $json : safeNode('PL_Load_Module_Registry');

// Fail-closed FIRST on verify failure — preserves original error_code (CONTEXT_MISMATCH, etc.).
if (verify && verify._verified === 'false') {
  return [{ json: {
    _context_ready: 'false',
    error_code: verify.error_code || 'CONTEXT_MISMATCH',
    error_message: verify.error_message || 'Execution context verification failed.',
    missing_fields: Array.isArray(verify.missing_fields) ? verify.missing_fields : []
  }}];
}

const plannerContext = (extract && extract.planner_context) || {};
const goal = String(plannerContext.goal || plannerContext.user_message_text || '').trim();
const primaryIntent = String(plannerContext.primary_intent || '').trim();
let requestedActions = Array.isArray(plannerContext.requested_actions) ? plannerContext.requested_actions.slice() : [];

const intentMap = {
  create_task: 'create_task', list_tasks: 'list_tasks', update_task: 'update_task',
  complete_task: 'complete_task', delete_task: 'delete_task',
  create_reminder: 'create_reminder', list_reminders: 'list_reminders',
  update_reminder: 'update_reminder', cancel_reminder: 'cancel_reminder',
  search_memory: 'search_memory', save_suggestion: 'capture_feedback'
};
const actionToModule = {
  create_task: 'task_module', list_tasks: 'task_module', update_task: 'task_module',
  complete_task: 'task_module', delete_task: 'task_module',
  create_reminder: 'reminder_module', list_reminders: 'reminder_module',
  update_reminder: 'reminder_module', cancel_reminder: 'reminder_module',
  search_memory: 'memory_module', capture_feedback: 'improvement_module',
  observe: 'watcher_module_basic'
};

if (!requestedActions.length && primaryIntent && intentMap[primaryIntent]) {
  const action = intentMap[primaryIntent];
  requestedActions = [{
    action,
    module_name: actionToModule[action],
    purpose: `Handle intent ${primaryIntent}`,
    inputs: plannerContext.inputs || {}
  }];
}

if (!goal) {
  return [{ json: {
    _context_ready: 'false',
    error_code: 'INSUFFICIENT_PLANNING_CONTEXT',
    error_message: 'Planning goal is missing.',
    missing_fields: ['planner_context.goal or planner_context.user_message_text']
  }}];
}
if (!requestedActions.length) {
  return [{ json: {
    _context_ready: 'false',
    error_code: 'INSUFFICIENT_PLANNING_CONTEXT',
    error_message: 'No requested actions or mappable primary intent are available.',
    missing_fields: ['planner_context.requested_actions or planner_context.primary_intent']
  }}];
}

return [{ json: {
  _context_ready: 'true',
  execution_id: String(verify.execution_id || ''),
  tenant_id: String(verify.tenant_id || ''),
  thread_id: String(verify.thread_id || ''),
  trigger_message_id: String(verify.trigger_message_id || ''),
  idempotency_key: String(verify.idempotency_key || ''),
  goal,
  primary_intent: primaryIntent || 'multi_action_request',
  requested_actions: requestedActions,
  module_registry: (registry && registry.module_registry) || [],
  warnings: Array.isArray(verify.warnings) ? verify.warnings : []
}}];

const actionToModule = {
  create_task: 'task_module',
  list_tasks: 'task_module',
  update_task: 'task_module',
  complete_task: 'task_module',
  delete_task: 'task_module',
  create_reminder: 'reminder_module',
  list_reminders: 'reminder_module',
  update_reminder: 'reminder_module',
  cancel_reminder: 'reminder_module',
  search_memory: 'memory_module',
  capture_feedback: 'improvement_module',
  observe: 'watcher_module_basic'
};
const steps = [];
for (let i = 0; i < ($json.requested_actions || []).length; i++) {
  const action = $json.requested_actions[i] || {};
  const actionName = String(action.action || '');
  const moduleName = String(action.module_name || actionToModule[actionName] || '');
  steps.push({
    step_id: `step_${String(i + 1).padStart(2, '0')}_${actionName || 'action'}`,
    module_name: moduleName,
    purpose: String(action.purpose || `Execute ${actionName}`),
    inputs: action.inputs || {},
    depends_on: action.depends_on || [],
    execution_mode: action.execution_mode || 'sequential',
    expected_outputs: action.expected_outputs || [],
    replan_if: action.replan_if || ['failed'],
    failure_policy: action.failure_policy || 'continue_with_notice',
    status: 'pending'
  });
}
return [{ json: {
  status_kind: 'success',
  result_type: 'plan',
  module_name: 'plan_generation',
  payload: {
    plan_id: `plan:${$json.execution_id}:v1`,
    execution_id: String($json.execution_id),
    thread_id: String($json.thread_id),
    goal: String($json.goal),
    primary_intent: String($json.primary_intent),
    reasoning_summary: `Generated ${steps.length} bounded step(s) from the validated orchestrator handoff.`,
    steps,
    allowed_next_stage: 'WF-DI-01',
    dispatcher_input: {
      dispatch_allowed: true,
      module_execution_started: false,
      response_generation_allowed: false,
      domain_writes_performed: false
    },
    warnings: Array.isArray($json.warnings) ? $json.warnings : []
  }
}}];

return [{ json: {
  status_kind: 'failed',
  result_type: 'error',
  module_name: 'plan_generation',
  error: {
    code: $json.error_code || 'PLAN_BUILD_FAILED',
    message: $json.error_message || 'Unknown planning error.',
    missing_fields: Array.isArray($json.missing_fields) ? $json.missing_fields : []
  }
}}];
